import{_ as o,E as t,h as r,c as d,b as e,f as p,H as i,a4 as n,w as c}from"./chunks/framework.B_fYP6Of.js";const v=JSON.parse('{"title":"Clean builds and release evidence","description":"Run the documentation checks on a clean machine, interpret the Rust and Python examples correctly, and see what a future hosted release still needs to prove.","frontmatter":{"title":"Clean builds and release evidence","description":"Run the documentation checks on a clean machine, interpret the Rust and Python examples correctly, and see what a future hosted release still needs to prove.","teaser":"What does a green build certify? Here it certifies a concrete set of documents and examples. A future application release has a different bar."},"headers":[],"relativePath":"engineering/clean-build.md","filePath":"engineering/clean-build.md"}'),h={name:"engineering/clean-build.md"};function u(m,a,b,k,g,f){const s=t("LabArticleHeader"),l=t("LabScroll");return r(),d("div",null,[a[1]||(a[1]=e("h1",{id:"clean-builds-and-release-evidence",tabindex:"-1"},[p("Clean builds and release evidence "),e("a",{class:"header-anchor",href:"#clean-builds-and-release-evidence","aria-label":'Permalink to "Clean builds and release evidence"'},"​")],-1)),i(s),a[2]||(a[2]=n(`<p>If a teammate starts from a clean checkout, they can build the documentation and run the synthetic exercises below. Each command has a visible result. Keep that record with the source revision so the next person can reproduce it.</p><p>The application release is a separate, proposed deliverable. Its command names and release gates are included here for design review. Only the documentation and example commands in the first section are runnable in this repository.</p><h2 id="documentation-runnable-now" tabindex="-1">Documentation: runnable now <a class="header-anchor" href="#documentation-runnable-now" aria-label="Permalink to &quot;Documentation: runnable now&quot;">​</a></h2><p>From a clean checkout with Node.js 22 or newer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/stream.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/publication.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-plan.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-pages.mjs</span></span></code></pre></div><p>The lease example uses a pinned Rust compiler. The following command runs its seven tests with the compiler’s default edition. The <a href="https://github.com/kaw393939/is373-rag/blob/main/.github/workflows/docs.yml" target="_blank" rel="noreferrer">documentation workflow</a> shows CI’s exact compiler invocation.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.90.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +1.90.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/lease.rs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ordo-lease-tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/ordo-lease-tests</span></span></code></pre></div><p>This compiler pin applies to a dependency-free documentation exercise, not a decision about the future runtime&#39;s supported toolchain. The application toolchain must be selected and security-reviewed at its own setup gate. The examples use synthetic data, no model credentials, no private donor checkout and no external service calls.</p><p>Read the output as an inventory of checks. The build covers Markdown links. The repository checker verifies generated destinations, the repository subpath, and the sitemap. Use a browser to examine the layout and keyboard behavior, test streaming against a running application, and visit the public URL to confirm a deployment.</p><h2 id="application-proposed-commands-not-available-yet" tabindex="-1">Application: proposed commands, not available yet <a class="header-anchor" href="#application-proposed-commands-not-available-yet" aria-label="Permalink to &quot;Application: proposed commands, not available yet&quot;">​</a></h2><p>The future workspace should expose a small process/administration interface, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lab api       # stateless public HTTP/SSE service</span></span>
<span class="line"><span>lab store     # private transaction owner and attached durable state</span></span>
<span class="line"><span>lab worker    # bounded capability execution</span></span>
<span class="line"><span>lab admin     # scoped migration, import, export, verify or repair</span></span>
<span class="line"><span>lab local     # explicit embedded-store authoring profile</span></span></code></pre></div><p>Treat these <code>lab</code> commands as an interface sketch. The docs-only repository does not supply executables with those names. When an implementation exists, test each process independently and tie its release evidence to the exact artifact being promoted.</p><p>Before implementation, pin the Rust toolchain and commit <code>Cargo.lock</code>; pin frontend dependencies and commit its lockfile. Declare ffmpeg/ffprobe and other external tools separately from Cargo dependencies. Each model manifest needs weights, tokenizer/preprocessing identity, dimensions where relevant, license/distribution policy and content hashes. A model name without an immutable identity is insufficient replay evidence.</p><p>For Rust builds, <code>--locked</code> requires the lockfile to remain unchanged; <code>--frozen</code> additionally requires offline operation. An offline build needs an intentionally prepared dependency cache or vendor source. Neither flag alone proves bit-for-bit reproducibility. <a href="https://doc.rust-lang.org/cargo/commands/cargo-build.html" target="_blank" rel="noreferrer">Cargo build options</a>.</p><h2 id="build-→-release-→-run" tabindex="-1">Build → release → run <a class="header-anchor" href="#build-→-release-→-run" aria-label="Permalink to &quot;Build → release → run&quot;">​</a></h2><p><strong>Build:</strong> verify source and dependency inputs, run unit/contract/integration tests, compile frontend and Rust binaries, produce a versioned image per supported architecture, record SBOM and scan results, then identify artifacts by digest.</p><p><strong>Release:</strong> combine an approved artifact with deployment configuration, schema compatibility, the published library revision and capability/model manifests. Validate migrations on a disposable copy and bind QA acceptance to that exact selection. Record a rollback or forward-repair procedure.</p><p><strong>Run:</strong> start the existing artifact. Do not install packages, compile source, download an unpinned model or migrate implicitly on every web-process startup. Readiness should report whether required storage/schema/capabilities are compatible without leaking credentials.</p><p>A failed release leaves the previous selection intact. Library publication and software deployment are separately versioned operations: updating the UI must not silently rewrite research evidence.</p><h2 id="required-evidence-before-a-hosted-release" tabindex="-1">Required evidence before a hosted release <a class="header-anchor" href="#required-evidence-before-a-hosted-release" aria-label="Permalink to &quot;Required evidence before a hosted release&quot;">​</a></h2>`,21)),i(l,{kind:"table",label:"table for Required evidence before a hosted release"},{default:c(()=>[...a[0]||(a[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Evidence"),e("th",{scope:"col"},"What it establishes"),e("th",{scope:"col"},"What it does not establish")])]),e("tbody",null,[e("tr",null,[e("td",null,"Locked clean build"),e("td",null,"Declared inputs can produce the artifact in that build environment"),e("td",null,"Universal bit-identical output on every platform")]),e("tr",null,[e("td",null,"Unit and contract tests"),e("td",null,"Covered rules hold for their fixtures"),e("td",null,"Production authorization or capacity by themselves")]),e("tr",null,[e("td",null,"SQLite integration tests"),e("td",null,"Transaction/constraint behavior on the selected engine"),e("td",null,"Correct remote filesystem behavior or distributed writer support")]),e("tr",null,[e("td",null,"Fault injection"),e("td",null,"Covered shutdown, replay and publication failures recover as designed"),e("td",null,"Every possible hardware fault")]),e("tr",null,[e("td",null,"Proxy/browser tests"),e("td",null,"Real framing, cancellation, session isolation and citations through HTTPS"),e("td",null,"Long-term service availability")]),e("tr",null,[e("td",null,"Restore rehearsal"),e("td",null,"Selected backup restores into an isolated compatible environment"),e("td",null,"That an untested provider snapshot is application-consistent")]),e("tr",null,[e("td",null,"Retrieval evaluation"),e("td",null,"Quality on a fixed reviewed set, including false matches"),e("td",null,"A universal confidence threshold")])])],-1)])]),_:1}),a[3]||(a[3]=n('<h2 id="platform-matrix" tabindex="-1">Platform matrix <a class="header-anchor" href="#platform-matrix" aria-label="Permalink to &quot;Platform matrix&quot;">​</a></h2><p>Use Linux QA with the production storage engine and deployment configuration shape. Test macOS authoring/export separately. Both consume the same schema/contract fixtures; the macOS run also tests missing-capability behavior when reopening its output on Linux.</p><p>Native acceleration is a separately qualified backend. Keep CPU/deterministic fixtures for protocol tests, but evaluate real embedding and media quality independently. Never replace an embedding model with a different model merely because the vector dimensions match.</p><h2 id="review-and-public-data-boundaries" tabindex="-1">Review and public-data boundaries <a class="header-anchor" href="#review-and-public-data-boundaries" aria-label="Permalink to &quot;Review and public-data boundaries&quot;">​</a></h2><p>Public examples contain synthetic data only. Public exports must be physically constructed from approved records and objects; a full database with hidden UI filters is not a public-safe export. Search indexes, deleted-page remnants, logs and manifests can also contain private content. Test export contents, not just the visible web page.</p><p>A clean checkout must not require the owner&#39;s <code>.env</code>, local home paths or private source repository. Imported source carries its provenance and applicable notices. The <a href="./../reuse/harvest-plan">harvest checklist</a> is part of the build gate, not optional housekeeping.</p>',6))])}const F=o(h,[["render",u]]);export{v as __pageData,F as default};
